      "answer": "The warning is non-rival because one listener does not reduce its availability to others. It is difficult to exclude people within earshot. People can benefit without paying, so a private provider may struggle to collect enough revenue to supply the service.",
      "kind": "Economic analysis",
      "minutes": 3,
      "href": "#/c/economics/term1/4"
