      "q": "Vaccination provides a benefit to people beyond the person vaccinated. Explain the market outcome and show how a subsidy can improve it.",
      "answer": "Draw marginal social benefit above marginal private benefit. The market quantity is where private benefit equals marginal cost. The efficient quantity is where social benefit equals marginal cost, at a higher output. A subsidy equal to the marginal external benefit at that output can align the private decision with the social benefit.",
