      "q": "One quantity cell contains a number stored as text. How can you check and repair it before totaling the column?",
      "answer": "Test the cell with ISNUMBER. If it returns FALSE for a numeric-looking value, convert the cell to a number using Convert to Number or VALUE, then recalculate the total.",
