      "topic": "复习与巩固",
      "q": "Compute a weighted average when scores are in B2:B4 and weights are in C2:C4. Weights need not sum to one.",
      "answer": "=SUMPRODUCT(B2:B4,C2:C4)/SUM(C2:C4). Divide by the total weight and verify it is positive.",
