      "topic": "复习与巩固",
      "q": "B2 holds a nominal annual interest rate. Compare annual and monthly compounding over one year on the principal in C2.",
      "answer": "Annual value =C2*(1+B2). Monthly value =C2*(1+B2/12)^12. Use a monthly rate for monthly compounding.",
