      "q": "Which statements apply to a T-account with a debit closing balance? Select all that apply.\nA. Debit entries exceed credit entries before balancing\nB. Balance c/d is placed on the credit side\nC. The next period's balance b/d is placed on the credit side\nD. The next period's balance b/d is placed on the debit side",
