      "q": "Which errors can leave the trial balance in agreement? Select all that apply.\nA. Omitting an entire transaction\nB. Posting equal debits and credits to the wrong accounts\nC. Omitting only the debit side of a nonzero entry\nD. Reversing both debit and credit accounts in an entry",
