      "q": "Which statements describe a columnar ledger with a running balance? Select all that apply.\nA. Update the balance after each posting\nB. Show whether the net balance is debit or credit\nC. Copy total debit and total credit movements separately into the trial balance\nD. A sufficiently large credit can change a debit balance into a credit balance",
