      "cid": "accounting",
      "cn": "会计学",
      "term": "term1",
      "week": 6,
      "topic": "Unit 7 · Concept questions",
      "q": "Which statements about transposition errors are correct? Select all that apply.\nA. Posting $450 on one side and $540 on the other can make the trial balance disagree\nB. Recording $450 instead of $540 on both sides can leave the trial balance equal\nC. A balanced trial balance proves no digits were transposed\nD. Posting just one side of an otherwise balanced entry can also make the totals disagree",
      "answer": "Correct choices: A, B, D.\nA. Correct. The two sides differ by $90.\nB. Correct. Both sides are wrong by the same amount.\nC. Incorrect. An error affecting both sides equally can escape the arithmetic check.\nD. Correct. An unmatched posting affects one total only.\nSource: Unit 7 lecture slides, pp. 18.",
      "minutes": 2,
      "kind": "会计概念多选",
