      "cid": "accounting",
      "cn": "会计学",
      "term": "term1",
      "week": 6,
      "topic": "Unit 7 · Concept questions",
      "q": "Which checks help reconcile a columnar ledger to a trial balance? Select all that apply.\nA. The trial balance can show account numbers alongside account names\nB. An account with a zero balance must add a positive amount to one total\nC. If the trial balance is for the end of February, use the last ledger balance as at that date\nD. The final running balance for the reporting date should match the net balance of the equivalent T-account",
      "answer": "Correct choices: A, C, D.\nA. Correct. The example uses identifiers from the chart of accounts.\nB. Incorrect. A zero balance contributes nothing to either total.\nC. Correct. A later March posting belongs to a later reporting date.\nD. Correct. The formats show the same underlying postings.\nSource: Unit 7 lecture slides, pp. 8–12, 16–17.",
