      "week": 5,
      "topic": "Unit 6 · Concept questions",
      "q": "A customer pays part of an outstanding credit balance into the business bank account. Which T-account postings correctly show the particulars? Select all that apply.\nA. Debit Cash at Bank and write the customer’s Accounts Receivable account in Particulars.\nB. Credit the customer’s Accounts Receivable account and write Cash at Bank in Particulars.\nC. Credit Sales and write Cash at Bank in Particulars.\nD. Debit Accounts Payable and write the customer’s name in Particulars.",
      "answer": "Correct choices: A, B.\nA. Correct. Cash increases and the particulars identify the account on the other side.\nB. Correct. The receivable decreases and the particulars identify the account on the other side.\nC. Incorrect. Sales revenue was recorded when the original credit sale occurred.\nD. Incorrect. The payment relates to a customer asset, with no supplier liability involved.\nSource: Unit 6 lecture slides, pp. 7–8, 14–22.",
      "minutes": 2,
      "kind": "会计概念多选",
      "href": "#/c/accounting/term1/5"
