      "term": "term1",
      "week": 6,
      "topic": "Unit 7 · Concept questions",
      "q": "A ledger account has a $900 credit balance. A $250 debit is posted, then a $700 debit. The trial balance is prepared immediately afterwards. Which statements are correct? Select all that apply.\nA. The first debit increases the balance to $1,150 credit.\nB. After the second debit the balance is $50 debit.\nC. The trial balance shows $950 in the debit column and $900 in the credit column for this account.\nD. The trial balance shows one $50 debit balance for this account.",
      "answer": "Correct choices: B, D.\nA. Incorrect. The opposite-side posting reduces the credit balance to $650.\nB. Correct. The second debit exceeds the remaining credit balance by $50.\nC. Incorrect. The trial balance reports the net amount from the account.\nD. Correct. The final running balance determines the amount and column.\nSource: Unit 7 lecture slides, pp. 5–11, 14–17.",
      "minutes": 2,
      "kind": "会计概念多选",
