      "topic": "Unit 1 · Concept questions",
      "q": "A supplier sends an invoice for goods sold on credit, then issues a credit note for goods returned before payment. Which statements are correct? Select all that apply.\nA. The invoice supplies evidence for recording the original sale.\nB. The credit note confirms the customer paid the full invoice.\nC. Both source documents can inform journal entries before posting to the ledger.\nD. The trial balance is where the invoice and credit note are first recorded.",
      "answer": "Correct choices: A, C.\nA. Correct. The invoice records the details of the credit sale.\nB. Incorrect. It is evidence of a reduction associated with the return. A receipt confirms payment.\nC. Correct. Source documents provide the details for original journal entry.\nD. Incorrect. The trial balance is prepared from ledger balances.\nSource: Unit 1 lecture slides, pp. 13–17.",
