      "term": "term1",
      "week": 1,
      "topic": "Unit 2 · Concept questions",
      "q": "Which statements about applying accounting conventions across reporting years are correct? Select all that apply.\nA. A justified change of method automatically breaches consistency.\nB. Regular reporting dates help users compare actual results with expected results.\nC. Going concern requires reporting only after a business ceases operations.\nD. Prudence calls for caution when a gain is highly uncertain.",
      "answer": "Correct choices: B, D.\nA. Incorrect. The convention permits justified changes in method.\nB. Correct. A defined interval gives users a basis for comparison.\nC. Incorrect. An ongoing business can prepare reports at regular intervals.\nD. Correct. Recognising a highly uncertain gain early can overstate performance.\nSource: Unit 2 lecture slides, pp. 9–10, 16–17.",
