      "term": "term1",
      "week": 2,
      "topic": "Unit 3 · Concept questions",
      "q": "A business buys resale stock for cash and buys a delivery van on credit. Which transaction analyses are correct? Select all that apply.\nA. Under periodic inventory, debit Purchases and credit Cash for the stock.\nB. Under perpetual inventory, debit Inventory and credit Cash for the stock.\nC. Debit Purchases for the delivery van because it was bought from a supplier.\nD. Credit Cash for the van at the time of purchase.",
      "answer": "Correct choices: A, B.\nA. Correct. The periodic method records the acquisition in Purchases.\nB. Correct. The inventory asset increases when stock is acquired.\nC. Incorrect. The van is a non-current asset held for business use.\nD. Incorrect. A credit purchase creates a payable. Cash is credited on payment.\nSource: Unit 3 lecture slides, pp. 9, 17–21, 29–35.",
      "minutes": 2,
      "kind": "会计概念多选",
      "href": "#/c/accounting/term1/2"
