      "cid": "accounting",
      "cn": "会计学",
      "term": "term1",
      "week": 3,
      "topic": "Unit 4 · Concept questions",
      "q": "A retailer returns part of a credit purchase before paying. The supplier offers a settlement discount on the remaining balance and the retailer qualifies for it. Which entries apply under the course’s periodic inventory treatment? Select all that apply.\nA. Debit Accounts Payable when the return is recorded.\nB. Debit Purchases Returns when the return is recorded.\nC. Debit Discount Allowed when paying the supplier.\nD. Debit Accounts Payable for the remaining balance at settlement.",
      "answer": "Correct choices: A, D.\nA. Correct. The return reduces the amount owed to the supplier.\nB. Incorrect. Purchases Returns is credited to reduce net purchases.\nC. Incorrect. The buyer receives the benefit and credits Discount Received.\nD. Correct. The payment and discount together clear the remaining liability.\nSource: Unit 4 lecture slides, pp. 10–19.",
      "minutes": 2,
      "kind": "会计概念多选",
