      "q": "Which statements correctly distinguish recording depreciation from accruing unpaid wages? Select all that apply.\nA. Both adjusting entries credit Cash.\nB. Depreciation debits an expense and credits a contra-asset.\nC. Unpaid wages debit an expense and credit a liability.\nD. Paying the accrued wages later requires recognising the same wages expense again.",
      "answer": "Correct choices: B, C.\nA. Incorrect. Neither adjustment moves cash.\nB. Correct. The credit increases accumulated depreciation against the asset.\nC. Correct. Workers have earned wages and the business owes payment.\nD. Incorrect. The previously accrued portion is debited to Wages Payable.\nSource: Unit 5 lecture slides, pp. 13–16, 20–22.",
