      "week": 5,
      "topic": "Unit 6 · Concept questions",
      "q": "Cash at Bank has total debits of $4,200 and total credits of $3,900 before balancing. Which T-account entries are correct? Select all that apply.\nA. Enter $300 as Balance c/d on the credit side at period end.\nB. Record $4,200 as the equal total on both sides after inserting Balance c/d.\nC. Bring down $300 as a credit balance at the start of the next period.\nD. Transfer $4,200 to the trial balance debit column.",
      "answer": "Correct choices: A, B.\nA. Correct. The credit side is smaller and receives the difference.\nB. Correct. The balancing line raises the smaller side to the larger total.\nC. Incorrect. The opening balance is debit because debits originally exceeded credits.\nD. Incorrect. Transfer the net debit balance of $300.\nSource: Unit 6 lecture slides, pp. 7–8, 24–31.",
