      "answer": "Correct choices: A, C.\nA. Correct. The debit balance reduces net sales.\nB. Incorrect. It is a contra-asset with a normal credit balance.\nC. Correct. The debit cost account and credit contra-asset are separate ledger balances.\nD. Incorrect. Posting the debit to another debit account could leave totals unchanged.\nSource: Unit 7 lecture slides, pp. 14–18.",
