      "answer": "Correct choices: A, B.\nA. Correct. Verification supports reliability.\nB. Correct. The lender needs it in time to act.\nC. Incorrect. Selective omission undermines reliability.\nD. Incorrect. Headings help understandability. Accuracy requires checking the figures.\nSource: Unit 1 lecture slides, pp. 12.",
