      "q": "A business omits adjustments for advance fees now earned and wages incurred but unpaid. Which statements are correct? Select all that apply.\nA. Unearned Revenue is overstated\nB. Wages Payable is overstated\nC. Revenue and expenses are both understated\nD. Profit is always overstated",
      "answer": "Correct choices: A, C.\nA. Correct. Earned fees should reduce the liability.\nB. Incorrect. The omitted accrual leaves the liability too low.\nC. Correct. Both amounts should be recognised in this period.\nD. Incorrect. The two omissions affect profit in opposite directions.\nSource: Unit 5 lecture slides, pp. 10–12, 20–22.",
