      "answer": "Correct choices: A, C.\nA. Correct. Revenue and expenses determine profit.\nB. Incorrect. The cash flow statement reports movements over a period.\nC. Correct. Liabilities form part of financial position at a date.\nD. Incorrect. The balance sheet reports equity at year-end.\nSource: Unit 1 lecture slides, pp. 16–17.",
