      "answer": "Correct choices: A, C.\nA. Correct. The service is consumed in January.\nB. Incorrect. The cash payment occurs in December.\nC. Correct. The reporting period divides an ongoing business life.\nD. Incorrect. Periodic reporting and continuity can coexist.\nSource: Unit 2 lecture slides, pp. 9–10, 14–15.",
