      "answer": "Correct choices: A, C.\nA. Correct. Equal postings leave no remaining balance.\nB. Incorrect. Other errors can still exist even when amounts offset.\nC. Correct. The amount carried forward is the net balance.\nD. Incorrect. A trial balance uses net balances.\nSource: Unit 6 lecture slides, pp. 7–8, 24–27.",
