      "answer": "Correct choices: A, C.\nA. Correct. The credit reduces the debit balance by $300.\nB. Incorrect. The posting belongs in the Credit column. Recalculate the Balance column.\nC. Correct. The recorded $1,100 exceeds the correct $500 by $600.\nD. Incorrect. The original debit balance exceeds the credit posting.\nSource: Unit 7 lecture slides, pp. 5–11, 14–18.",
