      "cid": "accounting",
      "cn": "会计学",
      "term": "term1",
      "week": 6,
      "topic": "Unit 7 · Concept questions",
      "q": "The trial balance lists a $540 debit balance twice. The ledger is correct and all other balances are copied once to the correct side. Which statements follow? Select all that apply.\nA. Debits exceed credits by $1,080.\nB. The trial balance debit total is overstated by $540.\nC. Remove the extra trial balance line.\nD. Post an additional $540 credit to the ledger.",
      "answer": "Correct choices: B, C.\nA. Incorrect. Only one of the two $540 lines is extra.\nB. Correct. The duplicate line adds one extra debit balance.\nC. Correct. The trial balance should list the ledger balance once.\nD. Incorrect. Correct the report. The ledger already has the right balance.\nSource: Unit 7 lecture slides, pp. 14-18.",
      "minutes": 2,
      "kind": "会计概念多选",
