      "topic": "Unit 7 · Concept questions",
      "q": "A bookkeeper records a complete journal entry at $640 instead of the correct $460. Both debit and credit postings use $640. Which statements follow? Select all that apply.\nA. The trial balance totals may remain equal.\nB. The transposition necessarily creates a $180 difference between columns.\nC. Comparing the entry to its source document can reveal the error.\nD. Agreement of the trial balance validates the transaction amount.",
      "answer": "Correct choices: A, C.\nA. Correct. Both sides were overstated by equal amounts.\nB. Incorrect. The $180 overstatement appears on both sides.\nC. Correct. The document establishes the original transaction amount.\nD. Incorrect. Equality cannot verify that both sides use the correct amount.\nSource: Unit 7 lecture slides, pp. 14-18.",
      "minutes": 2,
      "kind": "会计概念多选",
