      "week": 1,
      "topic": "Unit 2 · Concept questions",
      "q": "The owner withdraws cash for private use, and a client separately pays a fee for services performed in the previous period. Which statements apply under accrual accounting? Select all that apply.\nA. The withdrawal reduces equity through Drawings.\nB. The fee collection creates current-period revenue again.\nC. Collecting the fee reduces the existing receivable.\nD. The withdrawal is matched with service revenue as an operating cost.",
      "answer": "Correct choices: A, C.\nA. Correct. Business funds are taken for personal use.\nB. Incorrect. The fee was recognised when the service was performed.\nC. Correct. Cash replaces the claim against the customer.\nD. Incorrect. Drawings are an owner transaction.\nSource: Unit 2 lecture slides, pp. 7-8, 14-15.",
