      "topic": "Unit 4 · Concept questions",
      "q": "A retailer using periodic inventory returns $250 of unpaid merchandise to its supplier. Which statements describe the entry? Select all that apply.\nA. Debit Accounts Payable for $250.\nB. Credit Cash for $250.\nC. Credit Purchases Returns for $250.\nD. Debit Sales Returns for $250.",
      "answer": "Correct choices: A, C.\nA. Correct. The liability to the supplier decreases.\nB. Incorrect. No payment or refund occurs in this return of unpaid goods.\nC. Correct. The course uses a separate account to record the reduction in purchases.\nD. Incorrect. Sales Returns records goods returned by a customer.\nSource: Unit 4 lecture slides, pp. 18-21.",
