      "topic": "Unit 5 · Concept questions",
      "q": "A year-end adjustment debits Rent Expense and credits Prepaid Rent. Another debits Wages Expense and credits Wages Payable. Which statements are correct? Select all that apply.\nA. Both adjustments recognise costs incurred in the current period.\nB. Both adjustments decrease assets.\nC. Both adjustments reduce current-period profit.\nD. Both adjustments require a same-day payment.",
      "answer": "Correct choices: A, C.\nA. Correct. Rent has expired and wages have been earned by employees.\nB. Incorrect. The rent adjustment reduces an asset while the wages adjustment increases a liability.\nC. Correct. Each entry increases an expense.\nD. Incorrect. These entries recognise consumption and obligations independently of cash timing.\nSource: Unit 5 lecture slides, pp. 8-12, 20-22.",
