      "term": "term1",
      "week": 6,
      "topic": "Unit 7 · Concept questions",
      "q": "A complete journal entry for a cash purchase of equipment is posted with both sides reversed. Which statements are correct? Select all that apply.\nA. The trial balance can still agree.\nB. Cash is understated compared with the correct balance.\nC. Equipment is understated compared with the correct balance.\nD. Equal totals establish that the debit and credit directions are correct.",
      "answer": "Correct choices: A, C.\nA. Correct. The same amount appears as a debit and a credit despite the reversal.\nB. Incorrect. The incorrect debit increases Cash instead of reducing it.\nC. Correct. The incorrect credit reduces Equipment instead of increasing it.\nD. Incorrect. Trial balance equality does not detect a complete reversal.\nSource: Unit 7 lecture slides, pp. 14-18.",
      "minutes": 2,
      "kind": "会计概念多选",
