      "q": "An accountant prepares a budget for managers and a report for potential investors. Which statements are correct? Select all that apply.\nA. The budget can support internal planning.\nB. Potential investors may assess investment potential.\nC. The investor report gains reliability by omitting unfavourable transactions.\nD. Cost accounting is defined as preparing tax returns.",
      "answer": "Correct choices: A, B.\nA. Correct. Managers use prospective information to plan operations.\nB. Correct. They use financial information to evaluate the business.\nC. Incorrect. Selective omission undermines faithful reporting.\nD. Incorrect. Tax return preparation belongs to taxation accounting.\nSource: Unit 1 lecture slides, pp. 6-12.",
