      "q": "A periodic-inventory retailer buys resale goods partly for cash and partly on credit in one transaction. Which statements are correct? Select all that apply.\nA. The journal may have one debit and two credits.\nB. Every transaction must affect exactly two accounts.\nC. The total Purchases debit equals the combined credits.\nD. The unpaid portion is debited to Accounts Payable.",
      "answer": "Correct choices: A, C.\nA. Correct. Debit Purchases and credit Cash and Accounts Payable.\nB. Incorrect. Double entry permits more than two accounts.\nC. Correct. Each entry requires equal total debits and credits.\nD. Incorrect. The new supplier obligation increases with a credit.\nSource: Unit 3 lecture slides, pp. 29-37.",
