      "q": "A business writes off a customer balance using the direct write-off method. Which immediate effects follow? Select all that apply.\nA. Accounts Receivable decreases.\nB. Cash decreases by the written-off amount.\nC. Bad Debts Expense increases.\nD. The original sale must be recorded a second time.",
      "answer": "Correct choices: A, C.\nA. Correct. The credit removes the uncollectible claim.\nB. Incorrect. There is no cash movement in the write-off.\nC. Correct. The debit records the loss of the receivable.\nD. Incorrect. The write-off concerns recoverability of an existing balance.\nSource: Unit 4 lecture slides, pp. 26-27.",
