      "topic": "Unit 6 · Concept questions",
      "q": "A business debits Cash and credits Capital for an owner contribution. It later correctly posts both to T-accounts. Which statements distinguish posting from balancing? Select all that apply.\nA. Posting transfers the journal amounts to their individual accounts.\nB. Posting requires creating Balance c/d for every transaction.\nC. Balancing determines the difference between account debit and credit totals.\nD. Balancing converts the owner contribution into sales revenue.",
      "answer": "Correct choices: A, C.\nA. Correct. Cash receives a debit and Capital a credit.\nB. Incorrect. Balance c/d is used in periodic balancing.\nC. Correct. That difference is the net account balance.\nD. Incorrect. Capital remains an equity contribution.\nSource: Unit 6 lecture slides, pp. 7-8, 24-31.",
