      "q": "A business records a credit sale in dollars when goods are delivered and consistently applies that timing across periods. Which explanations are correct? Select all that apply.\nA. Recording in dollars applies monetary unit.\nB. Recording revenue at delivery despite later collection applies accrual accounting.\nC. Consistency requires recognising revenue on the date of cash collection.\nD. The entity convention combines the owner personal income with business revenue.",
      "answer": "Correct choices: A, B.\nA. Correct. The currency supplies the common financial measure.\nB. Correct. In this scenario delivery earns the sale revenue.\nC. Incorrect. Consistency concerns applying a chosen appropriate method across periods.\nD. Incorrect. Entity separates personal affairs from business transactions.\nSource: Unit 2 lecture slides, pp. 5-7, 14-16.",
