      "q": "Which comparisons between accrued revenue and unearned revenue are correct? Select all that apply.\nA. Accrued revenue has been earned before collection.\nB. Unearned revenue has been collected before performance.\nC. Both remaining balances are liabilities.\nD. Both adjusting entries debit Cash.",
      "answer": "Correct choices: A, B.\nA. Correct. The entity has a receivable for the amount earned.\nB. Correct. The entity owes goods or services to the customer.\nC. Incorrect. Accrued revenue produces an asset while unearned revenue is a liability.\nD. Incorrect. The adjustments recognise performance independently of the cash event.\nSource: Unit 5 lecture slides, pp. 10-12, 17-19.",
