      "q": "A complete cash sale of $900 is recorded twice, including both sides of each entry. Which statements describe the error? Select all that apply.\nA. Cash and Sales are each overstated by $900.\nB. Total debits must exceed total credits by $900.\nC. The trial balance may still agree.\nD. Changing only the Sales balance removes the whole error.",
      "answer": "Correct choices: A, C.\nA. Correct. One additional complete entry duplicates the original amounts.\nB. Incorrect. Both sides of the duplicate remain equal.\nC. Correct. Equality can coexist with duplicate complete entries.\nD. Incorrect. Both affected accounts require correction.\nSource: Unit 7 lecture slides, pp. 14-18.",
