      "answer": "Correct choices: A, B.\nA. Correct. It is the first book of entry.\nB. Correct. It collects movements affecting each account.\nC. Incorrect. Its balances cannot establish the details of every transaction.\nD. Incorrect. Ledger balances feed the trial balance and reporting process.\nSource: Unit 1 lecture slides, pp. 13-17.",
