      "answer": "Correct choices: B, C.\nA. Incorrect. Capital is excluded from profit. Revenue less expense gives $300.\nB. Correct. Add $800 and $500 and subtract $200.\nC. Correct. The $800 capital contribution and $300 profit both increase equity.\nD. Incorrect. An owner contribution is recorded as capital.\nSource: Unit 3 lecture slides, pp. 12-15, 22-23.",
