      "answer": "Correct choices: A, B.\nA. Correct. It fills the difference on the smaller side.\nB. Correct. The opening line preserves the debit net balance.\nC. Incorrect. It is a balancing line within the account.\nD. Incorrect. The actual net balance determines the trial balance column.\nSource: Unit 6 lecture slides, pp. 24-31.",
