      "q": "A sole trader transfers personal savings into the business bank account, then the business receives payment for services to be delivered next month. Which statements apply under accrual accounting? Select all that apply.\nA. The savings transfer is capital.\nB. Both receipts are revenue earned this month.\nC. The advance creates an obligation until the service is performed.\nD. Neither receipt changes business assets.",
      "answer": "Correct choices: A, C.\nA. Correct. It is an owner contribution to the entity.\nB. Incorrect. One receipt is capital and the other is an advance for future service.\nC. Correct. Unearned Revenue records the service owed.\nD. Incorrect. Both receipts increase business cash.\nSource: Unit 2 lecture slides, pp. 7-8, 14-15.",
