      "answer": "Correct choices: A, C.\nA. Correct. The buyer records the benefit of the reduction.\nB. Incorrect. The seller debits Discount Allowed as an expense.\nC. Correct. The reduction is a cost to the seller.\nD. Incorrect. Settlement clears the liability already recorded.\nSource: Unit 4 lecture slides, pp. 10-17.",
