      "q": "During a period an owner contributes $600 and withdraws $150. Revenue is $900 and expenses are $400. Which statements are correct? Select all that apply.\nA. Profit is $500.\nB. The net increase in equity is $950.\nC. Drawings reduce revenue to $750.\nD. Capital contributions form part of the $900 revenue.",
      "answer": "Correct choices: A, B.\nA. Correct. Subtract expenses from revenue.\nB. Correct. Add capital of $600 and profit of $500, then subtract drawings of $150.\nC. Incorrect. Drawings are separate from income earned.\nD. Incorrect. Capital records the owner investment separately.\nSource: Unit 3 lecture slides, pp. 12-15, 22-23.",
