      "answer": "Correct choices: A, B.\nA. Correct. Consumption reduces the asset and creates the expense.\nB. Correct. Performance reduces the obligation and creates revenue.\nC. Incorrect. Neither adjustment records a new cash movement.\nD. Incorrect. The prepaid asset decreases by credit.\nSource: Unit 5 lecture slides, pp. 8-12.",
