      "answer": "Correct choices: A, C.\nA. Correct. The credit exceeds the existing debit by $150.\nB. Incorrect. Actual postings determine the side of the net balance.\nC. Correct. The report uses the account balance at the reporting date.\nD. Incorrect. It uses one net balance for the account.\nSource: Unit 7 lecture slides, pp. 5-11, 14-17.",
