      "answer": "Correct choices: A, B.\nA. Correct. Source documents support journal recording.\nB. Correct. Comparability supports comparisons across reporting periods.\nC. Incorrect. Posting transfers journal amounts to individual accounts.\nD. Incorrect. Headings support understandability. Reliability requires faithful recording.\nSource: Unit 1 lecture slides, pp. 12-17.",
