      "week": 1,
      "topic": "Unit 2 · Concept questions",
      "q": "An owner pays a private bill from personal savings. Separately, the business provides services on credit. Which statements apply? Select all that apply.\nA. The private bill is a business expense.\nB. The credit service revenue is recognised when earned.\nC. The business records a receivable for the unpaid service fee.\nD. The private bill reduces business Capital automatically.",
      "answer": "Correct choices: B, C.\nA. Incorrect. Personal dealings are outside the business entity.\nB. Correct. Accrual accounting links revenue to performance.\nC. Correct. The customer owes the business for completed work.\nD. Incorrect. The owner used personal funds outside the business.\nSource: Unit 2 lecture slides, pp. 7-8, 14-15.",
