      "topic": "Unit 4 · Concept questions",
      "q": "A periodic-inventory retailer receives a credit note for goods it returned to a supplier before paying. Which statements are correct? Select all that apply.\nA. The credit note supports a reduction in Accounts Payable.\nB. The retailer debits Accounts Payable.\nC. The retailer credits Sales Returns.\nD. The retailer must credit Cash immediately.",
      "answer": "Correct choices: A, B.\nA. Correct. The supplier acknowledges the reduced amount due.\nB. Correct. The liability decreases.\nC. Incorrect. The return relates to purchases from a supplier.\nD. Incorrect. The goods were unpaid and the credit note changes the payable.\nSource: Unit 4 lecture slides, pp. 18-21.",
      "minutes": 2,
      "kind": "会计概念多选",
