      "topic": "Unit 6 · Concept questions",
      "q": "A business posts a $400 cash advertising payment to its T-accounts. The advertising service was used immediately. Which statements are correct? Select all that apply.\nA. Debit Advertising Expense and enter Cash as particulars.\nB. Credit Cash and enter Advertising Expense as particulars.\nC. Bring down the Cash gross debit total as its next opening balance.\nD. The advertising payment credits Advertising Expense.",
      "answer": "Correct choices: A, B.\nA. Correct. The expense increases and the particulars identify the matching account.\nB. Correct. The payment reduces cash.\nC. Incorrect. The opening balance is the net balance after all postings.\nD. Incorrect. An expense incurred increases with a debit.\nSource: Unit 6 lecture slides, pp. 7-8, 24-31.",
      "minutes": 2,
