      "topic": "Unit 7 · Concept questions",
      "q": "A correctly balanced trial balance includes an equipment purchase wrongly debited to Rent Expense. Which correcting entry fixes only this misclassification? Select all that apply.\nA. Debit Equipment for the misclassified amount.\nB. Credit Rent Expense for that amount.\nC. Credit Cash again for that amount.\nD. Debit Rent Expense again to preserve the original trial balance total.",
      "answer": "Correct choices: A, B.\nA. Correct. The equipment acquisition belongs in the asset account.\nB. Correct. The correction removes the incorrect expense debit.\nC. Incorrect. The original credit to Cash was already correct.\nD. Incorrect. An additional expense debit would worsen the error.\nSource: Unit 7 lecture slides, pp. 14-18.",
      "minutes": 2,
