      "week": 1,
      "topic": "Unit 1 · Concept questions",
      "q": "A potential investor asks about profitability, while a supplier asks about the amount owed at the reporting date. Which statements are correct? Select all that apply.\nA. The income statement helps assess profitability over a period.\nB. The balance sheet reports liabilities at a point in time.\nC. Both questions require only the cash flow statement.\nD. The supplier is an internal manager merely because it offers credit.",
      "answer": "Correct choices: A, B.\nA. Correct. It compares revenue and expenses for that period.\nB. Correct. It shows the financial position at the reporting date.\nC. Incorrect. Performance and position require the relevant statements.\nD. Incorrect. A supplier is an external user.\nSource: Unit 1 lecture slides, pp. 11-17.",
      "minutes": 2,
