      "topic": "Unit 3 · Concept questions",
      "q": "A business buys equipment on credit and separately earns a cash service fee. Which statements are correct? Select all that apply.\nA. The equipment purchase increases both an asset and a liability.\nB. The equipment purchase creates revenue.\nC. The fee increases Cash and Service Revenue.\nD. The cash fee must be credited to Capital.",
      "answer": "Correct choices: A, C.\nA. Correct. Debit Equipment and credit the payable.\nB. Incorrect. It acquires an asset and incurs an obligation.\nC. Correct. The service has been performed and payment received.\nD. Incorrect. Revenue arises from earning a fee. Capital records owner contributions.\nSource: Unit 3 lecture slides, pp. 10-15, 29-35.",
      "minutes": 2,
      "kind": "会计概念多选",
