      "topic": "Unit 4 · Concept questions",
      "q": "A customer owes $500 and pays $200. The remaining $300 is confirmed unrecoverable and written off directly. Which statements are correct? Select all that apply.\nA. The collection credits Accounts Receivable for $200.\nB. The write-off debits Bad Debts Expense for $300.\nC. The write-off credits Cash for $300.\nD. The total bad debt expense is $500.",
      "answer": "Correct choices: A, B.\nA. Correct. The payment reduces the customer balance.\nB. Correct. Only the unrecoverable remainder is expensed.\nC. Incorrect. No cash is collected or paid for the write-off.\nD. Incorrect. The customer already paid $200.\nSource: Unit 4 lecture slides, pp. 26-27.",
