      "q": "A business earns $300 on credit and incurs $120 of unpaid wages in the same period. Which effects follow under accrual accounting? Select all that apply.\nA. Assets increase by $300.\nB. Liabilities increase by $120.\nC. Cash increases by $180.\nD. Equity decreases by $180.",
      "answer": "Correct choices: A, B.\nA. Correct. The earned fee creates a receivable.\nB. Correct. The unpaid wages create an obligation.\nC. Incorrect. Neither transaction has yet moved cash.\nD. Incorrect. Revenue less expenses increases equity by $180.\nSource: Unit 2 lecture slides, pp. 11-15.",
