      "q": "A business has consumed $250 of prepaid insurance and incurred $400 of unpaid wages by year-end. Which credits belong in the adjusting entries? Select all that apply.\nA. Credit Prepaid Insurance for $250.\nB. Credit Cash for $650.\nC. Credit Wages Payable for $400.\nD. Credit Insurance Expense for $250.",
      "answer": "Correct choices: A, C.\nA. Correct. The expired portion reduces the asset.\nB. Incorrect. These adjustments record no cash movement.\nC. Correct. The business owes wages already incurred.\nD. Incorrect. The expense is increased by a debit.\nSource: Unit 5 lecture slides, pp. 8-9, 20-22.",
