      "q": "A supplier account opens with $900 Cr. A $200 purchase return and a $300 payment are then posted correctly. Which statements are correct? Select all that apply.\nA. The return is a debit to the supplier account.\nB. The payment is a credit to the supplier account.\nC. The closing balance is $400 Cr.\nD. The trial balance uses the original $900 Cr balance.",
      "answer": "Correct choices: A, C.\nA. Correct. Returning unpaid goods reduces the liability.\nB. Incorrect. Settlement reduces the liability with a debit.\nC. Correct. Subtract the $200 return and $300 payment from $900.\nD. Incorrect. Use the updated net balance of $400.\nSource: Unit 6 lecture slides, pp. 24-31.",
      "minutes": 2,
      "kind": "会计概念多选",
