      "q": "A credit sale is entered as a debit to Accounts Receivable and credit to Capital, both for the correct amount. Which statements are correct? Select all that apply.\nA. The trial balance may agree.\nB. Sales revenue is understated.\nC. Cash is overstated.\nD. Correcting the misclassification requires debiting Cash.",
      "answer": "Correct choices: A, B.\nA. Correct. The entry has equal debit and credit amounts.\nB. Correct. The credit that should have increased Sales went to Capital.\nC. Incorrect. This entry contains no Cash posting.\nD. Incorrect. Debit Capital and credit Sales to transfer the misclassified credit.\nSource: Unit 7 lecture slides, pp. 14-18.",
      "minutes": 2,
