      "answer": "Correct choices: A, C.\nA. Correct. Bookkeeping systematically records routine transactions.\nB. Incorrect. Management accounting supports internal budgets and pricing.\nC. Correct. It supplies information for planning and decisions.\nD. Incorrect. Auditing provides that review and assurance.\nSource: Unit 1 lecture slides, pp. 7-12.",
