      "answer": "Correct choices: A, B.\nA. Correct. The business acquires an asset.\nB. Correct. The contribution increases owner equity.\nC. Incorrect. An owner contribution is recorded separately from trading revenue.\nD. Incorrect. The contribution is an asset transfer with no cash receipt.\nSource: Unit 3 lecture slides, pp. 12-15, 29-35.",
