      "answer": "Correct choices: B, C.\nA. Incorrect. The cash received is $2,376.\nB. Correct. The discount is 1% of $2,400.\nC. Correct. The settlement clears the full balance.\nD. Incorrect. The seller debits Discount Allowed under the course treatment.\nSource: Unit 4 lecture slides, pp. 13-17.",
