      "answer": "Correct choices: A, B.\nA. Correct. Both increase the equipment asset.\nB. Correct. Add the opening balance and the two acquisitions.\nC. Incorrect. The credit goes to Cash.\nD. Incorrect. The balancing figure goes on the smaller credit side.\nSource: Unit 6 lecture slides, pp. 7-8, 24-31.",
