      "answer": "Correct choices: A, C.\nA. Correct. The report is missing the Equipment debit balance.\nB. Incorrect. The ledger transaction is already correct.\nC. Correct. This restores the omitted account balance.\nD. Incorrect. The asset has a debit balance and the report needs its inclusion.\nSource: Unit 7 lecture slides, pp. 14-18.",
