      "answer": "Correct choices: A, B.\nA. Correct. The trial balance uses account balances.\nB. Correct. It compares aggregate debit and credit balances.\nC. Incorrect. Documents supply details for initial journal entries.\nD. Incorrect. A complete omission can leave totals equal.\nSource: Unit 1 lecture slides, pp. 12-17.",
