      "answer": "Correct choices: A, C.\nA. Correct. The withdrawal and receipt offset in Cash.\nB. Incorrect. Collection clears a receivable previously recognised.\nC. Correct. The customer has paid the amount due.\nD. Incorrect. The withdrawal increases Drawings and reduces equity.\nSource: Unit 3 lecture slides, pp. 12-15, 29-35.",
