      "answer": "Correct choices: A, C.\nA. Correct. The two revenue credits add together.\nB. Incorrect. Enter the balancing figure on the smaller debit side.\nC. Correct. It reports the actual net account balance.\nD. Incorrect. The balanced totals include the balancing line and must not be added as revenue.\nSource: Unit 6 lecture slides, pp. 7-8, 24-31.",
