      "answer": "Correct choices: A, B.\nA. Correct. Both recognise costs of the period.\nB. Correct. Additional expenses reduce profit.\nC. Incorrect. Neither adjusting entry contains Cash.\nD. Incorrect. Wages credits a liability while depreciation credits a contra-asset.\nSource: Unit 5 lecture slides, pp. 13-16, 20-22.",
