      "topic": "Unit 7 · Concept questions",
      "q": "A $250 utilities expense is debited to Telephone Expense instead, and Cash is correctly credited. Which statements describe the error? Select all that apply.\nA. The trial balance can still agree.\nB. Total expenses are overstated by $250 solely because of this error.\nC. Utilities Expense is understated.\nD. Cash requires another $250 credit to fix the error.",
